/** @param {{des: object}} api */
export default function bigrm_7({ des, selection, math, luaList, luaLen }) {
    des.level_init({ style: 'solidfill', fg: ' ' });
    des.level_flags('mazelevel');

    des.map(`                                                        -----              
                                                ---------...---            
                                        ---------.........L...---          
                                ---------.......................---        
                        ---------.................................---      
                ---------...........................................---    
        ---------.....................................................---  
---------...............................................................---
|.........................................................................|
|.L.....................................................................L.|
|.........................................................................|
---...............................................................---------
  ---.....................................................---------        
    ---...........................................---------                
      ---.................................---------                        
        ---.......................---------                                
          ---...L.........---------                                        
            ---...---------                                                
              -----                                                        
`);

    // luaList keeps Lua's 1-based indices, so terrain[n] means the same here.
    const terrain = luaList('L', 'T', '{', '.');
    const tidx = math.random(1, luaLen(terrain));
    des.replace_terrain({ region: [0, 0, 74, 18], fromterrain: 'L', toterrain: terrain[tidx] });

    des.region(selection.area(1, 1, 73, 17), 'lit');

    des.stair('up');
    des.stair('down');

    des.non_diggable();

    for (let i = 1; i <= 15; i++) {
        des.object();
    }

    for (let i = 1; i <= 6; i++) {
        des.trap();
    }

    for (let i = 1; i <= 28; i++) {
        des.monster();
    }
}
